INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('anao-rochoso', 'Anão Rochoso', 'global', 'medio', '7,5 m', NULL, 'Os Guardiões das Cordilheiras. Vivem em enormes fortalezas nas montanhas, mestres da engenharia subterrânea e da arquitetura. São o pilar da identidade anã.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('anao-barba-de-bronze', 'Anão Barba de Bronze', 'global', 'medio', '9 m', NULL, 'Nascidos nas altas montanhas onde as tempestades são soberanas. Desenvolveram uma relação única com o poder dos céus, forjando com energia elétrica armazenada em elaborados condutores.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('anao-de-obsidea', 'Anão de Obsídea', 'global', 'medio', '7,5 m', NULL, 'Forjados no coração de montanhas vulcânicas. Pele negra como carvão e olhos alaranjados como brasas vivas. Considerados os melhores ferreiros que já caminharam sobre o mundo.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('elfo-altivo', 'Elfo Altivo', 'global', 'medio', '9 m', NULL, 'Herdeiros de tradições arcanas milenares, dedicados ao conhecimento e à diplomacia. Orgulhosos, com mente disciplinada e magia refinada como extensão natural de sua vontade.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('elfo-floral', 'Elfo Floral', 'global', 'medio', '12 m', NULL, 'Vivem entre ramos e raízes, conectados ao pulso da natureza. Ágeis como o vento e perigosos como predadores, combatem em harmonia com seus aliados.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('drow', 'Drow', 'global', 'medio', '9 m', NULL, 'Forjados nas profundezas do Subterrâneo. Caminham na tênue linha entre luz e trevas, mesclando astúcia e letalidade. Sua existência é marcada pela desconfiança e pelo instinto de sobrevivência.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('kor', 'Kor', 'global', 'medio', '9 m', NULL, 'Nascidos entre penhascos suspensos e ilhas flutuantes. Movem-se com graça de acrobatas e precisão de caçadores, usando cordas como extensão dos próprios braços.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('humano', 'Humano', 'global', 'medio', '9 m', NULL, 'A raça mais variada e adaptável. Não herdaram dons mágicos tão refinados quanto os elfos, nem a robustez dos anões, mas compensam com pura determinação e capacidade de aprender e inovar.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('gnomo-cabeca-de-ponta', 'Gnomo Cabeça de Ponta', 'global', 'pequeno', '6 m', NULL, 'Inventores incansáveis e estudiosos dedicados. Vivem cercados de pergaminhos e protótipos. Sua mente salta de ideia em ideia como uma faísca elétrica.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('gnomo-olhos-fundos', 'Gnomo Olhos Fundos', 'global', 'pequeno', '6 m', NULL, 'Brincalhões por natureza, enxergam o mundo como um palco para truques e ilusões. Mestres de confundir inimigos e proteger os seus com sombras e luz mágica.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('gnomo-nariz-afiado', 'Gnomo Nariz Afiado', 'global', 'pequeno', '6 m', NULL, 'Marcados por uma aura de imprevisibilidade e travessura. Carregam a sorte consigo — mas essa sorte tem seu preço. Mestres em manipular o destino.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('hobbit', 'Hobbit', 'global', 'pequeno', '7,5 m', NULL, 'Seres pequenos e alegres, amantes de boa refeição e conforto. Ágeis e habilidosos, com coragem surpreendente quando chamados à aventura.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('orc', 'Orc', 'global', 'medio', '10,5 m', NULL, 'Conhecidos por sua robustez e habilidades em combate. Sociedade estruturada em torno de líderes fortes e xamãs poderosos. Leais ao extremo com os seus, implacáveis com inimigos.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('tritao', 'Tritão', 'global', 'medio', '9 m / 12 m (natação)', NULL, 'Guardiões dos oceanos. Existência tão antiga quanto as marés. Cultura reflexo do oceano: ora calma, ora violenta. Lealdade à tribo e ao lar inabalável.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('aarakocra', 'Aarakocra', 'tribal', 'medio', '4,5 m / 15 m (voo)', NULL, 'Uma raça aviária nobre e aérea. Habitam comunidades em penhascos e árvores altas. Valorizam liberdade, honra e cooperação. Guardiões dos céus.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('feral-cervideo', 'Feral Cervídeo', 'tribal', 'medio', '12 m', NULL, 'Humanoides elegantes com chifres e pernas fortes que lembram veados ou alces. Forte senso de comunidade e proteção. Habitam florestas densas.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('feral-felix', 'Feral Felix', 'tribal', 'medio', '13,5 m', NULL, 'Reflexos rápidos e movimentos silenciosos com forte conexão com os felinos. Caçadores inatos, mestres da furtividade e da agilidade.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('feral-loxodonte', 'Feral Loxodonte', 'tribal', 'grande', '9 m', NULL, 'Constituição pesada ligada aos elefantes. São a rocha de sua comunidade. Vivem cerca de 450 anos e valorizam muito o peso da sabedoria e experiência.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('feral-marsupial', 'Feral Marsupial', 'tribal', 'medio', '9 m', NULL, 'Humanoides curiosos e resilientes com características de cangurus e coalas. Saltadores ágeis com forte conexão familiar.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('feral-mustelideo', 'Feral Mustelídeo', 'tribal', 'pequeno', '9 m', NULL, 'Humanoides ágeis e pequenos inspirados por lontras, furões e texugos. Inteligentes com habilidades de escavação e destreza em ambientes aquáticos e subterrâneos.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('feral-sarubino', 'Feral Sarubino', 'tribal', 'medio', '9 m', NULL, 'Inteligência e agilidade dos primatas. Curiosos e energéticos, exploradores natos com grande carisma e adaptabilidade. Cauda preênsil incrivelmente versátil.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('feral-taurus', 'Feral Taurus', 'tribal', 'medio', '9 m', NULL, 'Ferais robustos que personificam a força e a determinação dos touros. Comunidades pautadas em hierarquia de força e proteção.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('feral-ursanor', 'Feral Ursanor', 'tribal', 'medio', '9 m', NULL, 'Combinam a força bruta dos ursos com a sabedoria da floresta. Protetores ferozes de seus lares e famílias, inspirando medo e respeito em igual medida.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('feral-wonideo', 'Feral Wonideo', 'tribal', 'medio', '9 m', NULL, 'Natureza social com traços de lobos e cães. Lealdade inabalável, vivem em matilhas unidas e confiam na força do grupo.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('dracodile', 'Dracodile', 'tribal', 'medio', '9 m', NULL, 'Descendentes de Dracos. Predadores insaciáveis e ambiciosos com conexão inata à brutalidade. Um Dracodile nunca para de crescer (+0,5 m a cada 25 anos após maturidade).');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('draconato', 'Draconato', 'tribal', 'medio', '9 m', NULL, 'Descendentes diretos dos dragões. Cada um possui escamas de cor única refletindo sua linhagem. Portam habilidades naturais como sopro elemental e resistência a danos.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('genasi-da-agua', 'Genasi da Água', 'tribal', 'medio', '9 m / 12 m (natação)', NULL, 'Adaptáveis como o mar, podem ser calmos ou destrutivos. Pele azulada ou esverdeada, cabelos que se movem como água. Sentem profundo chamado por mares, rios e lagos.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('genasi-do-ar', 'Genasi do Ar', 'tribal', 'medio', '9 m', NULL, 'Personificação da liberdade e imprevisibilidade dos ventos. Nômades por natureza, aversão a confinamentos. Mente rápida como o vento e movimentos de ave de rapina.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('genasi-do-fogo', 'Genasi do Fogo', 'tribal', 'medio', '9 m', NULL, 'Personalidade intensa e volátil. Cabelos como chamas vivas, olhos que cintilam como brasas. Movidos por paixões fortes e pelo desejo de consumir e transformar.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('genasi-da-terra', 'Genasi da Terra', 'tribal', 'medio', '9 m', NULL, 'Resistentes e inabaláveis como a montanha. Pele como pedra com rachaduras que brilham como geodos. Aliados incrivelmente leais ou inimigos teimosos.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('githzerai', 'Githzerai', 'tribal', 'medio', '9 m', NULL, 'Monges e filósofos da raça Gith. Encontraram paz e disciplina no caos do Limbo. Buscam iluminação e mestria de corpos e mentes. Uma fortaleza de calma e concentração.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('githyanki', 'Githyanki', 'tribal', 'medio', '9 m', NULL, 'Guerreiros ferozes forjados pela escravidão e pela sede de poder. Dominam os planos com frota astral. A mente é tão potente quanto a espada.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('goliath', 'Goliath', 'tribal', 'grande', '10,5 m', NULL, 'Raça montanhosa robusta de clãs que valorizam resistência, competição e determinação. Reverenciam as montanhas como guias espirituais.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('thri-kreen', 'Thri-Kreen', 'tribal', 'medio', '12 m', NULL, 'Criaturas insetoides pragmáticas e diretas. Comunicação telepática entre iguais. Aversão inata à água. Exoesqueleto que age como armadura natural e múltiplos braços.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('aasimar-desprendido', 'Aasimar (Desprendido)', 'mistica', 'medio', '9 m', NULL, 'Livre das responsabilidades do bem e do mal. Não se importa com a dualidade celestial, vivendo com um grande senso de liberdade. Sub-raça revelada ao atingir o 3º nível.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('aasimar-enfurecido', 'Aasimar (Enfurecido)', 'mistica', 'medio', '9 m', NULL, 'Perdeu a piedade em sua cruzada contra o mal. Canaliza poder divino de forma explosiva e brutal. Demoli inimigos usando a ira para inspirar medo. Sub-raça revelada ao 3º nível.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('aasimar-piedoso', 'Aasimar (Piedoso)', 'mistica', 'medio', '9 m', NULL, 'Dedica sua vida a ter piedade dos outros. Protetor dos fracos e curador dos feridos. Um farol de esperança e fonte de poder vital. Sub-raça revelada ao 3º nível.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('firbolg', 'Firbolg', 'mistica', 'medio', '9 m', NULL, 'Manifestação física do poder primordial da natureza. Nascidos do coração das florestas. A última linha de defesa contra aqueles que corrompem o mundo natural.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('ghoul', 'Ghoul', 'mistica', 'medio', '9 m', NULL, 'Não nasceram, foram forjados no desespero. Fusão de uma raça à beira da extinção com a essência da necromancia. Predadores espectrais que habitam as sombras em busca de saciar sua sede.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('tiefling-diabo-da-mente', 'Tiefling (Diabo da Mente)', 'mistica', 'medio', '9 m', NULL, 'Prole do Pacto Infernal marcada pela herança do Diabo da Mente. Especialistas em conexões telepáticas e leitura de intenções. Linhagem voltada ao controle psíquico.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('tiefling-diabo-do-corpo', 'Tiefling (Diabo do Corpo)', 'mistica', 'medio', '9 m', NULL, 'Linhagem do Diabo do Corpo. Poder físico explosivo combinado com chamas infernais que transformam dor em força devastadora.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('tiefling-diabo-da-alma', 'Tiefling (Diabo da Alma)', 'mistica', 'medio', '9 m', NULL, 'Linhagem do Diabo da Alma. Mestres de encantamentos que controlam mentes e corações. Presença sedutora que atrai e desconcerta todos ao redor.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('saladins', 'Saladins', 'mistica', 'medio', '9 m', NULL, 'Originários de asteroides onde o Éter funciona como atmosfera densa. Curiosidade insaciável por tudo que é sólido. Suas histórias são tatuagens naturais que servem como brasões de linhagem.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('valdekeano', 'Valdekeano', 'mistica', 'medio', '9 m', NULL, 'Humanoides de intelecto brilhante e perigosa ambição. Fome extraordinária por conhecimento e arrogância ainda maior. Acreditam na própria superioridade sobre outras raças e deuses.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('silvestre', 'Silvestre', 'sobrenatural', 'medio', '12 m', NULL, 'Mistura intrigante de humano e besta. Capazes de se transformar em predadores selvagens sob influência de uma maldição. A lua cheia é tanto dom quanto maldição.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('transmorfo', 'Transmorfo', 'sobrenatural', 'medio', '9 m', NULL, 'Criaturas nascidas amaldiçoadas, nascidas de muitas formas. Ao nascer, assume a aparência da primeira pessoa vista, perdendo para sempre a chance de conhecer seu próprio rosto.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('ozzus', 'Ozzus', 'sobrenatural', 'medio', '9 m', NULL, 'Humanoides extraordinários de slimes adaptáveis com corpos amorfos. Pele lisa e reluzente em tons metálicos. Nascidos de metamorfoses mágicas que afetaram slimes muito antigos.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('warforged-servo', 'Warforged (Servo)', 'sobrenatural', 'medio', '9 m', NULL, 'Construto vivo criado para versatilidade e suporte. Especializado em auxiliar aliados e realizar tarefas específicas com precisão incomparável.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('warforged-colosso', 'Warforged (Colosso)', 'sobrenatural', 'medio', '9 m', NULL, 'Construto vivo construído para resistência e poder bruto. Quase inamovível, avança incansavelmente para batalha onde outros cairiam.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('warforged-sentinela', 'Warforged (Sentinela)', 'sobrenatural', 'medio', '9 m', NULL, 'Construto vivo otimizado para vigilância e proteção ativa de aliados. Escudo integrado que funciona tanto como defesa quanto como arma.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('grung', 'Grung', 'tribal', 'pequeno', '7,5 m / 7,5 m (escalada)', NULL, 'Pequenos humanoides anfíbios com aparência de sapos arborícolas. Ágeis, territorialistas e organizados em castas de cores vibrantes. Sua fofura esconde uma toxina letal para forasteiros.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('gungan', 'Gungan', 'tribal', 'medio', '9 m / 9 m (natação)', NULL, 'Habitantes de cidades submersas e pântanos densos. Conhecidos por seu estilo de vida exótico e por possuírem uma ''sorte caótica'', onde seus piores tropeços se convertem magicamente no infortúnio de seus inimigos.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('wookiee', 'Wookiee', 'tribal', 'grande', '9 m', NULL, 'Gigantes peludos com um senso de honra inabalável e uma força aterrorizante. Suas emoções são tão imensas quanto suas estaturas. São aliados leais e implacáveis no campo de batalha.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('kenku', 'Kenku', 'mistica', 'medio', '9 m', NULL, 'Corvos humanoides amaldiçoados a perderem suas asas e a própria voz. Eles sobrevivem à margem das sociedades aglomeradas copiando sons, forjando documentos e servindo em guildas perigosas.');
INSERT INTO racas (id, nome, categoria, tamanho, deslocamento, imagem_url, descricao) VALUES ('driade', 'Dríade', 'mistica', 'medio', '9 m', NULL, 'Seres nascidos do próprio coração das florestas. Feitas de casca, seiva e folhas, elas são a personificação da natureza protetora, radiando uma magia antiga de renovação e crescimento.');
