INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('kenku', 'Idade: amadurecem aos 12 anos, vivem cerca de 60 anos', 1);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('kenku', 'Tamanho: 1,50 m, ~45 kg — Médio', 2);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('kenku', 'Deslocamento: 9 m', 3);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('kenku', 'Lembrança Perfeita: você tem vantagem em testes para produzir falsificações ou cópias exatas de manuscritos e artesanatos', 4);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('kenku', 'Idiomas: Apenas sons copiados, porém entende Comum e Auran', 5);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('driade', 'Aumento de Sabedoria +2 e Carisma +1', 0);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('driade', 'Idade: atrelada à árvore ou bioma de origem, podendo viver milênios', 1);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('driade', 'Tamanho: 1,60–1,80 m — Médio', 2);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('driade', 'Deslocamento: 9 m', 3);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('driade', 'Natureza Arbórea: você é considerado um ser Feérico em vez de humanoide. Não precisa comer ou dormir (apenas tomar sol e água)', 4);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('driade', 'Vulnerabilidade Vegetal: vulnerabilidade a dano de Fogo', 5);
INSERT INTO raca_tracos (raca_id, texto, ordem) VALUES ('driade', 'Idiomas: Comum e Silvestre', 6);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-rochoso', 'Visão Sísmica', 'Você possui visão sísmica a até 9 metros.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-rochoso', 'Corpo de Colosso', 'Seu máximo de pontos de vida aumenta em 1. A cada nível, recebe vida adicional igual à metade do seu bônus de proficiência (mínimo 1).', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-rochoso', 'Bastião Ancestral', '+1 de CA enquanto estiver usando armadura.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-rochoso', 'Proteção Rúnica', 'Vantagem em testes de resistência contra magias de nível igual ou inferior ao seu modificador de Constituição.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-rochoso', 'Especialização em Artesanato', 'Você possui especialização na perícia de ferramenta recebida pela característica de raça.', 4);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-barba-de-bronze', 'Resistência Elétrica', 'Você tem resistência a dano elétrico.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-barba-de-bronze', 'Energético por Natureza', 'Vantagem em testes para resistir à Exaustão. Ao terminar um descanso curto ou longo, recupera um nível de Exaustão adicional.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-barba-de-bronze', 'Corpo Eletromagnético', 'Vantagem em jogadas de ataque corpo a corpo contra criaturas feitas de metal ou usando armaduras de metal. Vantagem em testes de Força em qualquer interação com metal.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-barba-de-bronze', 'Velocidade Energizada', 'Seu deslocamento base de caminhada é de 9 metros.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-de-obsidea', 'Resistência Vulcânica', 'Você tem resistência a dano de fogo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-de-obsidea', 'Armas da Forja Viva', 'Uma vez por descanso curto ou longo, ao atingir um inimigo com arma corpo a corpo de metal, causa 1d8 de dano de fogo adicional (2d8 no 11º nível).', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-de-obsidea', 'Teimosia de Pedra', 'Você só morre após falhar em 4 testes de resistência contra a morte, em vez de 3.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('anao-de-obsidea', 'Forjador-Mestre', 'Proficiência com ferramentas de ferreiro. Tempo de criação/reparo de metal reduzido à metade. Armas ou armaduras criadas por você recebem bônus em ataque/CA igual à metade do bônus de proficiência. Número de itens com bônus cresce por nível (1 no 1º, 3 no 2º, 6 no 3º, etc.).', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('elfo-altivo', 'Magia Altiva', 'Aprende dois truques de Mago. No 3º nível, aprende uma magia de 1º nível de Mago; no 5º nível, uma de 2º nível. Cada magia de nível pode ser conjurada uma vez por descanso longo sem gastar espaço.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('elfo-altivo', 'Mente Diplomática', 'Vantagem no primeiro teste de Carisma ao interagir com uma criatura. Após o primeiro teste, a criatura só é afetada novamente após 24h.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('elfo-floral', 'Ataque de Primavera', 'Ao realizar um ataque corpo a corpo, você não provoca ataques de oportunidade daquela criatura pelo resto do turno.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('elfo-floral', 'Instinto de Matilha', '+1 na jogada de ataque para cada aliado a até 3 metros do alvo, até o máximo do bônus de proficiência. Aliados inconscientes ou incapacitados não contam.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('elfo-floral', 'Magia Feérica', 'Conjura Fogo das Fadas gratuitamente. No 3º nível: Crescer Espinhos. No 5º nível: Falar com Plantas. Cada magia recupera uso após descanso longo. Sabedoria é o atributo de conjuração.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('elfo-floral', 'Máscara da Natureza', '+5 em testes de Furtividade em leve obscuridade por folhagem, chuva, neve, névoa ou fenômenos naturais.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('drow', 'Resistência Necrótica', 'Você tem resistência a danos necróticos.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('drow', 'Teleporte Sombrio', 'Ação bônus: teleporta até 9m para ponto levemente obscurecido (não estando em fonte de luz). Ganha resistência a todos os danos até o início do próximo turno. Recupera uso após descanso longo.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('drow', 'Lâmina do Pacto Sombrio', 'Ao final de um descanso curto, gasta 1 pv para banhar uma arma cortante/perfurante no sangue. O primeiro ataque que acertar causa dano necrótico adicional igual a 1/10 do pv máximo da criatura (ignora resistências) e impede a criatura de recuperar pv até o início do próximo turno. Uma arma por vez.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('kor', 'Escalada Kor', 'Proficiência nas perícias Atletismo e Acrobacia.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('kor', 'Sorte Sobre o Destino', 'Ao rolar 1 no d20 em ataque, teste ou resistência, pode rolar novamente e usar o novo resultado.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('kor', 'Bravura', 'Vantagem em testes para resistir a ser amedrontado.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('kor', 'Mestres do Chicote', 'Proficiência com chicote, cujo dado de dano passa a ser d8. Com o chicote em mãos: saltos 3x maiores e, com uma reação, pode fazer teste de Acrobacia para negar dano de queda no valor igual ao resultado do teste.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('humano', 'Perícia', 'Você ganha proficiência em duas perícias à sua escolha.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('humano', 'Talento', 'Você adquire um talento de sua escolha.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gnomo-cabeca-de-ponta', 'Ilusionista Nato', 'Conhece o truque Ilusão Menor. Inteligência é o atributo de conjuração.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gnomo-cabeca-de-ponta', 'Curioso', 'Proficiência em Investigação e vantagem em testes de Destreza (Investigação).', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gnomo-cabeca-de-ponta', 'Sabido', 'Proficiência em uma ferramenta de artesão à escolha. Sempre que usar essa ferramenta, adiciona 1d6 à rolagem.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gnomo-cabeca-de-ponta', 'Epifania Caótica', 'Ao iniciar um descanso longo, cria uma engenhoca que replica uma magia aleatória de até nível igual à metade do seu nível. Pode usá-la uma vez antes do próximo descanso longo. A engenhoca é pessoal e intransferível.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gnomo-cabeca-de-ponta', 'Magia Gnômica', 'Conhece um truque e uma magia de 1º nível de Mago (escola de Transmutação). Pode conjurar a magia uma vez por descanso longo. Inteligência é o atributo de conjuração.', 4);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gnomo-olhos-fundos', 'Magia Gnômica', 'Conhece um truque e uma magia de 1º nível de Mago (escola de Ilusão). Pode conjurar a magia uma vez por descanso longo. Inteligência é o atributo de conjuração.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gnomo-olhos-fundos', 'Pó de Pirlimpimpim', 'Ao ser atingido por um ataque, como reação, lança pó mágico: reduz o dano pela metade e torna-se invisível até o início do próximo turno (ou até atacar/conjurar). Durante a invisibilidade, pode se mover sem provocar ataques de oportunidade. Usos iguais ao bônus de proficiência por descanso longo.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gnomo-nariz-afiado', 'Sorte Inconstante', 'Como reação, toca uma criatura e concede vantagem em uma rolagem à escolha. Se o resultado for maior que metade do valor máximo do dado, é tratado como máximo; se menor que metade, o resultado é dobrado. O alvo recebe ''marca de azar'' por 1 hora: –1d4 em todas as rolagens de d20. Usos iguais ao bônus de proficiência por descanso longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gnomo-nariz-afiado', 'Magia da Sorte', 'Conhece o truque Orientação. No 3º nível, pode conjurar Benção uma vez por descanso longo. Carisma é o atributo de conjuração.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('hobbit', 'Mãos Ágeis', 'Proficiência em Prestidigitação e vantagem em testes de Destreza (Prestidigitação).', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('hobbit', 'Rosto Inocente', 'Proficiência em Persuasão e Atuação. Especialização em uma dessas perícias à escolha.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('orc', 'Frenesi Desenfreado', 'Como reação ao ser atingido por ataque corpo a corpo, realiza um ataque corpo a corpo com arma com vantagem contra o atacante. Recupera uso após descanso curto ou longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('orc', 'Ataques Selvagens', 'Ao realizar um acerto crítico com arma corpo a corpo, rola um dos dados de dano da arma uma vez a mais e adiciona ao dano extra do crítico.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tritao', 'Frenesi da Corrente Sanguínea', 'Ao atacar corpo a corpo criatura com menos da metade do pv, tem vantagem na jogada de ataque. Em um acerto, causa dano extra igual ao bônus de proficiência.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tritao', 'Tinta do Mar Profundo', 'Reação ao ser atacado: libera nuvem de tinta em 3 m ao redor. Área fica obscurecida por 1 minuto e o atacante tem desvantagem no ataque. Recupera uso após descanso curto ou longo.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tritao', 'Choque da Enguia', 'Resistência a dano elétrico. Como ação, choca criatura a até 3 m: teste de Constituição (CD 8 + proficiência + Car). Em falha, criatura fica paralisada por rodadas iguais ao bônus de proficiência. Repete o teste ao fim de cada turno. Usos iguais ao bônus de proficiência por descanso longo.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('aarakocra', 'Olhos de Águia', 'Proficiência em Percepção com dobro do bônus. Enxerga normalmente até 4 km de distância.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('aarakocra', 'Viajante', 'Quando voando sem exceder limite de peso, pode cobrir até 3.000 km em um único dia com magia secreta aarakocra.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('aarakocra', 'Esquiva', 'Reação ao ser alvejado: levanta voo e move 4,5 m em qualquer direção sem provocar ataques de oportunidade, ganhando +5 de CA contra aquele ataque.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-cervideo', 'Chifres Naturais', 'Nunca está desarmado. Chifres causam 1d8 de dano perfurante e garantem vantagem em testes para empurrar criaturas.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-cervideo', 'Fuga Instintiva', 'Reação ao ser atingido por ataque corpo a corpo: move até metade do deslocamento sem provocar ataques de oportunidade.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-cervideo', 'Presença Tranquilizadora', 'Ação: força criaturas hostis em 6 m a fazerem teste de Sabedoria (CD 8 + proficiência + Sab) ou ficarem encantadas por 1 minuto. Uma vez por descanso longo.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-felix', 'Agilidade Felina', 'Pode dobrar seu deslocamento até o fim do turno. Após usar, não pode usar novamente até ficar parado por um turno.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-felix', 'Garras de Gato', 'Garras são armas naturais: 1d4 + modificador de Força de dano cortante. Permite escalar superfícies com deslocamento de 6 m.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-loxodonte', 'Olfato Aguçado', 'Vantagem nos testes de Sabedoria (Percepção) e Inteligência (Investigação) que dependem do olfato.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-marsupial', 'Investida Saltadora', 'Ao usar Correr e atacar corpo a corpo no mesmo turno, causa dano adicional igual ao bônus de proficiência.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-marsupial', 'Resistência Natural', 'Ao recuperar pv em descanso curto, rola 1d6 adicional e adiciona ao resultado.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-marsupial', 'Aderência Ágil', 'Vantagem em testes de Força ou Destreza para resistir a quedas ou se agarrar em superfícies.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-marsupial', 'Instinto de Proteção', 'Reação: quando aliado em 6 m for alvo de ataque, pode se mover até 4,5 m em sua direção.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-mustelideo', 'Mordida Venenosa', 'Mordida causa 1d6 de dano perfurante. O alvo faz teste de Constituição (CD 8 + proficiência + Con). Em falha: 1d4 de dano de veneno adicional e desvantagem no próximo ataque.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-mustelideo', 'Investida Ágil', 'Uma vez por turno, ao fazer ataque corpo a corpo, pode usar ação bônus para mover 3 m sem provocar ataques de oportunidade.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-sarubino', 'Quebra de Limites', 'Reação: ao falhar em teste de Força, Destreza ou Constituição, pode refazer e usar o novo resultado. Recupera uso após descanso longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-sarubino', 'Cauda', 'Pode usar a cauda para: (1) interagir com objetos/ferramentas; (2) agarrar criatura de tamanho igual ou menor; (3) cumprir componentes somáticos. Se não usar a cauda no turno, ganha bônus de CA igual ao bônus de proficiência.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-taurus', 'Chifres', 'Nunca está desarmado. Proficiência com chifres (arma corpo a corpo, 1d10 de dano perfurante). Vantagem em testes para empurrar criaturas (mas não para evitar ser empurrado).', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-taurus', 'Passos Pesados', 'Ao mover mais de 3 m em linha reta, criaturas Médias ou menores em 1,5 m ao redor fazem teste de Destreza (CD 8 + proficiência + For) ou são derrubadas.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-taurus', 'Arremete com Chifres', 'Ao usar Correr no turno, pode fazer ataque com chifres como ação bônus.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-taurus', 'Pancada com Chifres', 'Ao usar Atacar com ataque corpo a corpo, pode tentar encontrão com os chifres como ação bônus (não pode derrubar com este encontrão).', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-ursanor', 'Fúria do Predador', 'Ao atingir inimigo com ataque corpo a corpo, pode ativar Fúria do Predador: causa dano extra igual ao bônus de proficiência até o fim do próximo turno. Usos iguais ao modificador de Constituição (mínimo 1) por descanso longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-ursanor', 'Pancada Poderosa', 'Ataques desarmados com garras causam 1d8 + modificador de Força de dano cortante.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-ursanor', 'Hibernar', 'Recupera o dobro de pv em descanso curto. Pode dormir profundamente por 24 horas para eliminar todos os níveis de exaustão acumulados.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-wonideo', 'Instinto de Matilha', 'Reação: quando aliado a 1,5 m faz ataque corpo a corpo contra criatura, pode realizar um ataque corpo a corpo contra a mesma criatura.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-wonideo', 'Uivo Inspirador', 'Ação: uivo que concede pv temporários iguais ao nível + modificador de Sabedoria a todos os aliados em 9 m que puderem ouvir. Recupera uso após descanso curto ou longo.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('feral-wonideo', 'Presa Selvagem', 'Ataques desarmados com mandíbulas causam 1d6 + modificador de Força de dano perfurante.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('dracodile', 'Sexto Sentido Predatório', 'Ação: detecta criaturas em raio crescente (6 m no 1º, 18 m no 5º, 54 m no 11º, 1 km no 16º). Sabe a direção e se o ND é maior, igual ou menor que o nível. Funciona através de paredes finas. Usos iguais ao bônus de proficiência por descanso longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('dracodile', 'Devorador Compulsivo', 'Ação: devora criatura caída (morta há menos de 1 minuto, até uma categoria de tamanho menor). Recupera pv iguais ao ND da criatura + nível do personagem.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('dracodile', 'Mandíbulas Famintas', 'Ação bônus: ataque de mordida (1d6/2d6/4d6/6d6 de dano perfurante por nível) + pode agarrar o alvo + ganha pv temporários iguais ao nível. Se levar criatura a 0 pv, pode usar Devorador Compulsivo automaticamente. Usos iguais ao bônus de proficiência por descanso longo.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('draconato', 'Ancestral Dracônico', 'Escolha o tipo de dragão ancestral (Azul, Branco, Bronze, Cobre, Latão, Negro, Ouro, Prata, Verde ou Vermelho) para determinar o tipo de dano e a forma da Arma de Sopro (linha ou cone).', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('draconato', 'Arma de Sopro', 'Ação: exala energia destrutiva. CD = 8 + mod de Constituição ou Carisma + bônus de proficiência. Dano: 3d6 (6º: 7d6, 11º: 12d6, 16º: 18d6, 20º: 25d6). Metade do dano em sucesso. Usos iguais ao bônus de proficiência por descanso longo.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-da-agua', 'Absorção de Energia', 'Ação: recupera 2d6 pv (3d6 no 6º, 4d6 no 11º, 5d6 no 16º). Recupera uso após descanso curto ou longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-da-agua', 'Magia Elemental', 'Conhece o truque Moldar Água. No 3º nível: conjura Criar ou Destruir Água (2º nível) sem componentes materiais, uma vez por descanso curto/longo. Constituição é o atributo de conjuração.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-da-agua', 'Escudo de Bolhas', 'A partir do 3º nível, após descanso longo cria pv temporários iguais ao nível × bônus de proficiência. Pode consumir 20 L de água com uma ação para recarregar o escudo.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-da-agua', 'Manifestação Elemental', 'A partir do 5º nível, conjura Invocar Elemental (tipo Água) no nível do bônus de proficiência, sem concentração. Duração base de 1 hora, dobrada por nível acima do 3º. Uma vez por descanso longo.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-do-ar', 'Absorção de Energia', 'Ação: recupera 2d6 pv (3d6 no 6º, 4d6 no 11º, 5d6 no 16º). Recupera uso após descanso curto ou longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-do-ar', 'Queda Suave', 'Enquanto cai e não estiver incapacitado, pode subtrair até 60 m de queda para cálculo de dano e mover 120 cm horizontalmente para cada 30 cm de queda.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-do-ar', 'Misturar-se ao Vento', 'Conhece o truque Lufada. No 3º nível: conjura Levitação sem componentes materiais, uma vez por descanso curto/longo. Constituição é o atributo de conjuração.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-do-ar', 'Agilidade do Vento', 'A partir do 3º nível, recebe bônus na CA contra ataques à distância e em resistências de Destreza, ambos iguais ao bônus de proficiência.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-do-ar', 'Manifestação Elemental', 'A partir do 5º nível, conjura Invocar Elemental (tipo Ar) no nível do bônus de proficiência, sem concentração. Uma vez por descanso longo.', 4);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-do-fogo', 'Absorção de Energia', 'Ação: recupera 2d6 pv (3d6 no 6º, 4d6 no 11º, 5d6 no 16º). Recupera uso após descanso curto ou longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-do-fogo', 'Alcançar as Chamas', 'Conhece o truque Criar Chamas. No 3º nível: conjura Mãos Flamejantes (1º nível) sem componentes materiais, uma vez por descanso curto/longo. Constituição é o atributo de conjuração.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-do-fogo', 'Chama Convergente', 'A partir do 3º nível, ao acertar um ataque, pode fazer o ataque explodir em chamas: dano adicional de fogo = (bônus de proficiência – 1)d8. Criaturas em 1,5 m do alvo também sofrem o dano. Usos iguais ao bônus de proficiência por descanso longo.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-do-fogo', 'Manifestação Elemental', 'A partir do 5º nível, conjura Invocar Elemental (tipo Fogo) no nível do bônus de proficiência, sem concentração. Uma vez por descanso longo.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-da-terra', 'Absorção de Energia', 'Ação: recupera 2d6 pv (3d6 no 6º, 4d6 no 11º, 5d6 no 16º). Recupera uso após descanso curto ou longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-da-terra', 'Desmoronar Rochas', 'Conhece o truque Orientação. No 3º nível: conjura Onda Trovejante sem componentes materiais, uma vez por descanso curto/longo. Constituição é o atributo de conjuração.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-da-terra', 'Corpo Resiliente', 'Reduz todo dano Cortante, Perfurante e Contundente em um valor igual ao bônus de proficiência. Aplica-se antes de qualquer resistência.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('genasi-da-terra', 'Manifestação Elemental', 'A partir do 5º nível, conjura Invocar Elemental (tipo Terra) no nível do bônus de proficiência, sem concentração. Uma vez por descanso longo.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('githzerai', 'Poder Psíquico', 'Conhece o truque Mão Mágica (sempre invisível). Considerada Psiônica.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('githzerai', 'Mente Fortalecida pelo Transe', 'Após descanso longo, escolhe: Aura de Calma (pv temporários = nível + mod Sab) ou Foco Psíquico (vantagem em resistências de Sabedoria até o próximo descanso longo).', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('githzerai', 'Defesa Psíquica', 'Reação: quando criatura em 9 m realiza ataque, causa desvantagem na jogada. Usos iguais ao bônus de proficiência por descanso longo.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('githyanki', 'Poder Psíquico', 'Conhece o truque Mão Mágica (sempre invisível). Considerada Psiônica.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('githyanki', 'Êxtase do Conquistador', 'Ao realizar acerto crítico, recebe +1 em jogadas de acerto até o fim do combate.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('githyanki', 'Fúria do Conquistador', 'Uma vez por turno, após ver o resultado de ataque/resistência/perícia mas antes do mestre declarar sucesso/falha, pode adicionar dado extra: 1d4 se não estiver com pv máximo; +1d4 se ≤ 50% pv; +1d8 se com 1 pv.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('githyanki', 'Resiliência pela Raiva', 'Ao ser reduzido a 0 pv (sem morte instantânea), pode fazer resistência: 1d12 + mod Constituição + nível. Se total > dano recebido que o zerou, fica com 1 pv.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('goliath', 'Resistência da Pedra', 'Reação ao sofrer dano: rola 1d12 + modificador de Constituição e reduz o dano por esse valor. Usos iguais ao bônus de proficiência por descanso curto ou longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('thri-kreen', 'Carapaça Camaleônica', 'Ação bônus: muda cor/textura da carapaça para se camuflar. Vantagem em testes de Furtividade até o início do próximo turno.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('thri-kreen', 'Exoesqueleto', 'CA = 13 + modificador de Destreza sem armadura.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('thri-kreen', 'Múltiplos Membros', 'No início de cada turno, escolhe: Postura Defensiva (bônus na CA e em resistências/testes de Destreza = bônus de proficiência) ou Postura Ofensiva (dano extra em ataques corpo a corpo = bônus de proficiência; bônus em resistências/testes de Força = bônus de proficiência).', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('aasimar-desprendido', 'Alma Radiante', 'Ação: libera energia divina (olhos reluzem, asas incorpóreas surgem). Dura 1 minuto ou até encerrar com ação bônus. Uma vez por turno, causa dano extra radiante igual ao nível ao causar dano com ataque ou magia. Uma vez por descanso longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('aasimar-enfurecido', 'Demolidor de Covardes', 'Ao atingir criatura Amedrontada, sua CA é reduzida em –1. Todos os pontos perdidos retornam após descanso curto.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('aasimar-enfurecido', 'Manto Trovejante', 'Ação bônus: olhos relampejam, asas trovejantes surgem. Criaturas em 9 m que puderem ver você fazem teste de Carisma (CD 8 + proficiência + Car) ou ficam Amedrontadas até o fim do próximo turno. Dura 1 minuto. Uma vez por turno, causa dano trovejante extra igual ao nível + bônus de CA igual ao bônus de proficiência. Uma vez por descanso longo.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('aasimar-piedoso', 'Palavra Curativa', 'Ação bônus: conjura Palavra Curativa no nível igual ao bônus de proficiência. Carisma é o atributo de conjuração. Uma vez por descanso longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('aasimar-piedoso', 'Salvar os Caídos', 'Criaturas à sua escolha em 3 m têm vantagem em resistências a veneno e testes de resistência à morte.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('aasimar-piedoso', 'Benção Radiante', 'Ação: irradia luz reconfortante (intensa em 3 m, penumbra em +3 m). No fim de cada turno, você e criaturas à sua escolha em 3 m recuperam pv iguais ao nível. Dura 1 minuto. Uma vez por descanso longo.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('firbolg', 'Pele de Gaia', 'Reação ao sofrer dano Ácido, Elétrico, Fogo, Gélido ou Trovejante: recebe resistência àquele tipo. Como parte da reação, pode realizar um ataque mágico à distância em alvo a 9 m (usa Sabedoria), causando dano igual ao dano que teria tomado. Uma vez por descanso curto ou longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('firbolg', 'Toque de Fartura', 'Ação bônus: toca criatura voluntária. Por 1 minuto: pv temporários = 3× o nível, bônus em testes de Força/resistências de Força = bônus de proficiência, e aumenta uma categoria de tamanho. Não funciona em construtos ou mortos-vivos. 5% de chance de se tornar permanente em animais. Uma vez por descanso longo.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('firbolg', 'Colheita Mística', 'Ação: conjura uma árvore em ponto visível a 9 m. A árvore tem 15 m de altura, raio de 3 m e produz 1d4/1d6/1d8/2d10/3d12 frutos por nível. Ação bônus: criatura toca a árvore e recebe fruto que recupera 10% da vida máxima, sacia e aplica Restauração Menor. Após os frutos acabarem, 5% de chance de permanecer (dá novos frutos a cada 3 meses); caso contrário murcha em 24 h.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('ghoul', 'Ferrão do Pavor', 'Ação bônus: ataque com ferrão da cauda (1d8 de dano perfurante). O alvo faz teste de Sabedoria (CD 8 + proficiência + Con). Em falha: Amedrontado por 1 minuto (repete o teste ao fim de cada turno). Usos iguais ao bônus de proficiência por descanso longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('ghoul', 'Sede de Sangue', 'Ao causar dano com ataque corpo a corpo em criatura que não seja morto-vivo, construto ou planta, recupera pv iguais ao bônus de proficiência.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tiefling-diabo-da-mente', 'Telepatia', 'Ação bônus: escolhe criatura visível em 9 m. Vocês podem falar telepaticamente a até 1 km por nível. Ambos devem conhecer o idioma usado.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tiefling-diabo-da-mente', 'Intuição Avançada', 'Em testes de Intuição para detectar mentiras, é considerado proficiente e adiciona o dobro do bônus de proficiência.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tiefling-diabo-da-mente', 'Leitura Mental', 'A partir do 5º nível: conjura Detectar Pensamentos uma vez por descanso longo sem gastar espaço de magia. Carisma é o atributo de conjuração.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tiefling-diabo-do-corpo', 'Chamas do Sangue', 'Ao ser atingido por ataque corpo a corpo, pode liberar explosão de chamas em 3 m: dano de fogo igual ao nível. Cura-se em todo o dano causado. Recupera uso após descanso curto ou longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tiefling-diabo-do-corpo', 'Proeza Física', 'Proficiência em Atletismo (especialização se já for proficiente).', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tiefling-diabo-do-corpo', 'Toque Infernal', 'A partir do 5º nível: conjura Infligir Ferimentos (nível 2) uma vez por descanso longo sem gastar espaço. Carisma é o atributo de conjuração.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tiefling-diabo-da-alma', 'Favor do Encantador', 'Criaturas encantadas por suas magias de Encantamento recebem bônus à escolha (CA, ataque ou resistências) igual à metade do bônus de proficiência. Dura enquanto o encantamento permanecer.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tiefling-diabo-da-alma', 'Aura de Tentação', 'Proficiência em Persuasão e Enganação (especialização em uma delas se já for proficiente).', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('tiefling-diabo-da-alma', 'Beijo Infernal', 'A partir do 5º nível: conjura Enfeitiçar Pessoa (nível 2) uma vez por descanso longo sem gastar espaço. Em falha na resistência, pode causar 2d6 de dano psíquico adicional. Carisma é o atributo de conjuração.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('saladins', 'Cauda de Conjunção', 'Pode realizar componentes somáticos e verbais de magias usando apenas a cauda. Se cortada, regenera em 1d4 semanas.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('saladins', 'Mãos Mágicas Invisíveis', 'Enquanto tiver magia armazenada na cauda, pode conjurar Mãos Mágicas como magia invisível. Alcance: 9m + 3m por nível da magia; carga: 2^nível em kg.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('saladins', 'Bateria e Sobrecarga de Éter', 'Ao final de descanso longo, armazena um espaço de magia na cauda. Pode usá-lo para conjurar uma magia ou ''queimá-lo'' para bônus em Ataque de Magia / CD de Resistência igual ao nível do espaço consumido.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('saladins', 'Imunidade de Ressonância', 'Com magia armazenada na cauda, ganha imunidade a qualquer magia da mesma escola da armazenada, desde que a magia agressora seja de nível igual ou inferior.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('valdekeano', 'Telepatia', 'Comunica-se telepaticamente com criaturas em 9 m (deve compartilhar idioma). Criaturas sem telepatia podem receber e responder, mas não iniciar.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('valdekeano', 'Troca de Memória', 'Pode mostrar memórias a outras criaturas com um toque. Se não voluntário, faz teste de Carisma (CD 12 + mod Int do alvo). O alvo pode ver e memorizar completamente as memórias compartilhadas.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('valdekeano', 'Magia Profunda', 'Conhece Mind Sliver. No 3º nível: Sussurros Dissonantes. No 5º nível: Detectar Pensamentos. Pode usar cada uma (nível 1+) um número de vezes igual ao bônus de proficiência por descanso longo. Sem componentes. Inteligência, Sabedoria ou Carisma (à escolha na criação) é o atributo de conjuração.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('silvestre', 'Besta Fera', 'A partir do 3º nível. Ação bônus: assume aparência bestial por 1 minuto (ou até morrer / cair a 0 pv / ser atingido por crítico com arma de prata). Efeitos: pv máximo temporariamente aumentado em 2 × (proficiência + nível); cresce uma categoria de tamanho; bônus em CA e ataques/dano corpo a corpo = metade do bônus de proficiência; desvantagem em testes de Inteligência; resistência a dano não mágico (exceto prata). Uma vez por descanso curto ou longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('silvestre', 'Terror da Lua Cheia', 'Em noite de lua cheia, ao entrar em contato com a luz da lua, transforma-se na Besta Fera até o fim da noite (ou 0 pv / crítico de prata). Torna-se extremamente agressivo e territorialista, incapaz de distinguir amigos de inimigos.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('transmorfo', 'Sussurro do Abismo', 'Ação: sussurra desorientação a humanoide visível em 9 m. CD = 8 + proficiência + Car. Para cada ponto que o ND da criatura for menor que o nível do personagem, a CD aumenta em 1. Em falha: criatura cai no sono. Acordada por dano ou por alguém gastando uma ação para sacudi-la. Imune por 24 h após resistir ou ser acordada de forma não natural.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('transmorfo', 'Mudar Aparência', 'Ação: transforma-se na aparência de qualquer humanoide tocado. Galeria de Ecos armazena 3× o nível em aparências. Pode armazenar nova aparência ao tocar um humanoide (substituindo uma existente). Roupas e equipamentos não mudam. Vantagem em Enganação para evitar detecção.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('transmorfo', 'Invasor de Consciência', 'Ação: ao tocar humanoide dormindo, faz teste de Intuição. Em sucesso, aprende personalidade, comportamento, maneirismos e pensamento recente da criatura. Recebe dado bônus (1d4/1d6/1d8/1d12 com resultado 10–15/16–20/21–25/26–30) em testes de Enganação, Persuasão ou Atuação para se passar por ela.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('ozzus', 'Rebote Flexível', 'Reação ao ser atingido por ataque corpo a corpo: reduz o dano em 1d6 + modificador de Constituição e pode se mover até 3 m sem provocar ataques de oportunidade.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('warforged-servo', 'Design Especializado', 'Proficiência em uma perícia, uma ferramenta (kit de erbalismo, ferramentas de ferreiro, instrumento musical, etc.) e um idioma adicional.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('warforged-servo', 'Mestre da Assistência', 'Ao usar a ação de Ajudar, a criatura beneficiada ganha bônus adicional igual ao bônus de proficiência na rolagem de ataque ou teste de habilidade.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('warforged-servo', 'Ferramentas Integradas', 'Escolhe uma ferramenta com proficiência. Pode usá-la sem precisar segurá-la (integrada ao corpo). Dobra o bônus de proficiência com essa ferramenta.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('warforged-servo', 'Modo de Serviço', 'Em descanso curto, pode realizar tarefa utilitária (consertar equipamentos, cozinhar, preparar armadilha) sem perder os benefícios do descanso.', 3);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('warforged-colosso', 'Construção Sólida', 'No início de cada turno (com pelo menos 1 pv), ganha pv temporários iguais ao bônus de proficiência.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('warforged-colosso', 'Corpo Resiliente', 'Reduz todo dano Cortante, Perfurante e Contundente em um valor igual ao bônus de proficiência. Aplica-se antes de qualquer resistência.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('warforged-sentinela', 'Escudo Integrado', 'Ação bônus: integra escudo especial a uma das mãos. Concede +1 adicional à CA além do bônus normal de escudo. Pode usá-lo como arma (1d6 de dano contundente). Ao atingir uma criatura de tamanho igual ou menor, pode empurrá-la 1,5 m.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('warforged-sentinela', 'Proteção Instintiva', 'Uma vez por descanso curto: reação para interpor o escudo entre aliado em 1,5 m e um ataque sofrido, concedendo +2 de CA contra aquele ataque.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('grung', 'Pele Tóxica', 'Sua pele secreta uma toxina natural. Sempre que uma criatura agarrar você ou for agarrada por você, ela sofre 1d4 de dano de veneno no início do turno dela. Além disso, uma vez por turno ao acertar um ataque corpo a corpo desarmado ou com armas perfurantes, você pode forçar o alvo a fazer um teste de Constituição (CD 8 + sua proficiência + sua Constituição) ou ficar envenenado até o final do próximo turno do alvo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('grung', 'Salto Arbóreo', 'Sua distância de salto em distância ou altura é sempre dobrada. Você não precisa realizar movimentação prévia (teste de corrida) para alcançar a distância máxima dos seus saltos.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gungan', 'Atrapalhada Contagiosa', 'Quando você falha em uma jogada de ataque, teste de habilidade ou teste de resistência, você pode usar sua reação para transformar o erro em um desastre em cadeia. Uma criatura hostil a até 9 metros de você deve realizar um teste de Destreza (CD 8 + sua proficiência + seu Carisma). Se falhar, ela sofre desvantagem em sua próxima jogada ou deixa cair a arma que estiver segurando (sua escolha). Usos iguais ao bônus de proficiência por descanso longo.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('gungan', 'Mergulhador Ágil', 'Movimentar-se na água, lama espessa ou pântanos não custa deslocamento adicional. Além disso, você tem proficiência em Acrobacia.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('wookiee', 'Pelagem de Ferro', 'Sua pelagem espessa e músculos densos lhe concedem resistência a dano cortante. Além disso, você tem vantagem em testes de resistência para evitar a Exaustão e não requer mais que 4 horas de descanso para recuperar as energias.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('wookiee', 'Grito de Guerra Ancestral', 'Como uma ação bônus no seu primeiro turno de um combate, você emite um rugido ensurdecedor. Até o final do seu próximo turno, todos os aliados a até 9 metros que puderem ouvi-lo ganham vantagem em sua primeira jogada de ataque e recebem pontos de vida temporários iguais ao seu nível + seu modificador de Força. Você pode usar essa habilidade uma vez por descanso longo.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('wookiee', 'Fúria do Vínculo', 'Se um aliado que você possa ver for reduzido a 0 pontos de vida, você tem vantagem nas jogadas de ataque corpo a corpo no seu próximo turno contra o atacante.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('kenku', 'Mimetismo', 'Você pode imitar perfeitamente sons que ouviu, incluindo vozes. Uma criatura que ouça os sons só pode perceber que são imitações se passar em um teste de Sabedoria (Intuição) resistido pelo seu Carisma (Enganação).', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('kenku', 'Treinamento do Bando', 'Você tem proficiência em duas perícias à sua escolha entre: Acrobacia, Enganação, Furtividade ou Prestidigitação.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('kenku', 'Emboscada Ecoante', 'Sempre que atacar uma criatura que esteja surpresa, você causa um dano adicional igual ao seu bônus de proficiência. Você pode usar seu mimetismo como uma Ação Bônus para distrair ou assustar alvos em combate.', 2);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('driade', 'Camuflagem da Floresta', 'Se você estiver em um ambiente natural (floresta, pântano, etc.) e passar pelo menos 1 turno completamente imóvel, você recebe um bônus de +10 no seu próximo teste de Furtividade e conta como invisível para quem estiver a mais de 9 metros de você.', 0);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('driade', 'Essência Verdejante', 'A energia da vida corre forte em sua seiva. Sempre que você recuperar pontos de vida através de uma magia que não seja da escola de Necromancia, você recupera o dobro do valor rolado nos dados.', 1);
INSERT INTO raca_habilidades (raca_id, nome, descricao, ordem) VALUES ('driade', 'Magia Silvestre', 'Você conhece o truque Druidismo. A partir do 3º nível, pode conjurar Constrição uma vez por descanso longo. A partir do 5º nível, pode conjurar Pele de Árvore uma vez por descanso longo. Sua Sabedoria é o atributo de conjuração.', 2);